<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Order extends Model { protected $fillable=['order_number','email','first_name','last_name','phone','address1','address2','city','state','postal_code','country','subtotal','shipping','tax','total','status','payment_status','payment_reference']; protected $casts=['subtotal'=>'decimal:2','shipping'=>'decimal:2','tax'=>'decimal:2','total'=>'decimal:2']; public function items(){return $this->hasMany(OrderItem::class);} }